// ---- Errors ----

/**
 * The component's arguments break the contract. The message lists every
 * problem, one per line, and never contains a secret's value.
 */
export class ConfigViolation extends pulumi.ResourceError {
  readonly problems: string[];
  constructor(component: string, problems: string[], resource: pulumi.Resource | undefined) {
    super(
      `${component}: ${problems.length} configuration problem${problems.length === 1 ? "" : "s"}:\n` + problems.map((p) => `  ${p}`).join("\n"),
      resource,
      true,
    );
    this.name = "ConfigViolation";
    this.problems = problems;
  }
}

// ---- Sources ----

const VAR_SOURCES = ["value", "secretKeyRef", "configMapKeyRef", "fieldRef", "resourceFieldRef", "injected"] as const;
const FILE_SOURCES = ["inline", "configMap", "secret", "certificate", "csi", "image", "injected"] as const;

/** The sources a variable accepts on the kubernetes target (SPEC.md 4.5). */
export function varSources(v: ContractVar): string[] {
  if (v.secret || v.type === "keySet") return ["secretKeyRef", "injected"];
  const s = ["value"];
  if (v.type !== "list") s.push("configMapKeyRef");
  if (v.type === "string") s.push("fieldRef");
  if (v.type === "int") s.push("resourceFieldRef");
  return [...s, "injected"];
}

/** The sources a file input accepts (#CheckFile). */
export function fileSources(f: ContractFile): string[] {
  if (f.secret) return f.type === "tls" ? ["secret", "certificate", "csi", "injected"] : ["secret", "csi", "injected"];
  const s: string[] = [];
  if (f.type !== "binary") s.push("inline");
  s.push("configMap", "secret");
  if (f.type === "tls") s.push("certificate");
  return [...s, "csi", "image", "injected"];
}

function isSecret(v: ContractVar): boolean {
  return v.secret === true || v.type === "keySet";
}

/** The one source key an argument sets, or undefined. */
function sourceOf(arg: unknown, kinds: readonly string[]): string | undefined {
  if (!isObj(arg)) return undefined;
  const set = Object.keys(arg).filter((k) => arg[k] !== undefined && arg[k] !== null);
  return set.length === 1 && kinds.includes(set[0]!) ? set[0] : undefined;
}

function orList(xs: string[]): string {
  return xs.length < 2 ? xs.join("") : `${xs.slice(0, -1).join(", ")} or ${xs[xs.length - 1]}`;
}

function isObj(x: unknown): x is Obj {
  return typeof x === "object" && x !== null && !Array.isArray(x) && !pulumi.Output.isInstance(x);
}

// ---- Values as the app reads them (wire) and as Kubernetes needs them ----

const DURATION = /^([0-9]+(ns|us|ms|s|m|h))+$/;
const MS: Record<string, number> = { ms: 1, s: 1000, m: 60000, h: 3600000 };

/**
 * A duration as [whole milliseconds, nanoseconds left over], exact for any
 * duration up to thousands of years without BigInt.
 */
function durationParts(d: string): [number, number] {
  let ms = 0;
  let ns = 0;
  for (const m of d.matchAll(/([0-9]+)(ns|us|ms|s|m|h)/g)) {
    const n = Number(m[1]);
    if (m[2] === "ns") ns += n;
    else if (m[2] === "us") ns += n * 1000;
    else ms += n * MS[m[2]!]!;
  }
  return [ms + Math.floor(ns / 1e6), ns % 1e6];
}

function durationLess(a: string, b: string): boolean {
  const [am, an] = durationParts(a);
  const [bm, bn] = durationParts(b);
  return am < bm || (am === bm && an < bn);
}

/** A duration in its encoding (#RenderDuration). */
export function renderDuration(d: string, encoding = "go"): string {
  if (encoding === "go" || !DURATION.test(d)) return d;
  const ms = durationParts(d)[0];
  const secs = Math.floor(ms / 1000);
  const frac = ms % 1000;
  const fracStr = frac === 0 ? "" : "." + String(frac).padStart(3, "0").replace(/0+$/, "");
  if (encoding === "seconds") return `${secs}${fracStr}`;
  if (encoding === "iso8601") return `PT${secs}${fracStr}S`;
  const pad = (n: number) => String(n).padStart(2, "0");
  const days = Math.floor(secs / 86400);
  return `${days > 0 ? `${days}.` : ""}${pad(Math.floor((secs % 86400) / 3600))}:${pad(Math.floor((secs % 3600) / 60))}:${pad(secs % 60)}${fracStr}`;
}

function replaceAll(s: string, from: string, to: string): string {
  return s.split(from).join(to);
}

/** JSON as #Render writes it: compact, with U+2028 and U+2029 escaped. */
function marshal(x: unknown): string {
  return JSON.stringify(x).replace(/\u2028/g, "\\u2028").replace(/\u2029/g, "\\u2029");
}

/** Kubernetes expands $(VAR) in env values and reduces $$ to $, so every $ is doubled. */
function esc(s: string): string {
  return replaceAll(s, "$", "$$");
}

/** A literal's env entries as the app reads them, before Kubernetes escaping (#RenderVar). */
export function wireEntries(name: string, v: ContractVar, x: unknown): { name: string; value: string }[] {
  if (v.type === "json") return [{ name, value: marshal(x) }];
  if (v.type === "list") {
    const items = Array.isArray(x) ? x : [x];
    const enc = v.encoding ?? "csv";
    if (enc === "json") return [{ name, value: marshal(items) }];
    if (enc === "indexed") return items.map((i, n) => ({ name: `${name}__${n}`, value: String(i) }));
    return [{ name, value: items.map(String).join(v.separator ?? ",") }];
  }
  if (v.type === "duration") return [{ name, value: renderDuration(String(x), v.encoding) }];
  return [{ name, value: String(x) }];
}

function renderVar(name: string, v: ContractVar, arg: Obj): EnvVar[] {
  const kind = sourceOf(arg, VAR_SOURCES)!;
  const src = arg[kind];
  if (kind === "injected") {
    const ref = (src as Obj)["ref"];
    return typeof ref === "string" && ref !== "" ? [{ name, value: esc(ref) }] : [];
  }
  if (kind !== "value") return [{ name, valueFrom: { [kind]: src } }];
  return wireEntries(name, v, src).map((e) => ({ name: e.name, value: esc(e.value) }));
}

// ---- Files (#RenderFile) ----

function mountDir(f: ContractFile): string {
  return f.type === "tls" ? f.path : posix.dirname(f.path);
}

/** The text an inline source puts in the file (#InlineContent). */
export function inlineContent(f: ContractFile, inline: unknown): string {
  if (typeof inline === "string") return inline;
  switch (f.format) {
    case "json":
      return marshal(inline);
    case "toml":
      return tomlStringify(inline as Obj);
    default:
      return yamlStringify(inline);
  }
}

function hash10(s: string): string {
  return createHash("sha256").update(s, "utf8").digest("hex").slice(0, 10);
}

interface FileParts {
  env: EnvVar[];
  volumes: Volume[];
  volumeMounts: VolumeMount[];
  configMaps: ConfigMapSpec[];
  restartTriggers: RestartTrigger[];
}

function renderFile(service: string, name: string, f: ContractFile, arg: Obj): FileParts {
  const kind = sourceOf(arg, FILE_SOURCES)!;
  const s = arg[kind] as Obj;
  const vol = `dc-${name}`;
  const fileName = posix.basename(f.path);
  const mode = f.secret ? 0o400 : 0o444;
  const out: FileParts = { env: [], volumes: [], volumeMounts: [], configMaps: [], restartTriggers: [] };
  if (f.pathEnv) out.env.push({ name: f.pathEnv, value: esc(f.path) });
  if (kind === "injected") return out;
  const restart = (k: RestartTrigger["kind"], n: unknown) => {
    if (f.reload === "restart") out.restartTriggers.push({ kind: k, name: n as string });
  };
  let volume: Volume;
  switch (kind) {
    case "inline": {
      const content = inlineContent(f, s);
      const cm = `${service}-${name}-${hash10(content)}`;
      volume = { name: vol, configMap: { name: cm, defaultMode: mode, items: [{ key: fileName, path: fileName }] } };
      out.configMaps.push({ name: cm, data: { [fileName]: content }, immutable: true });
      break;
    }
    case "configMap":
      volume = { name: vol, configMap: { name: s["name"] as string, defaultMode: mode, items: [{ key: s["key"] as string, path: fileName }] } };
      restart("ConfigMap", s["name"]);
      break;
    case "secret":
      volume =
        f.type === "tls"
          ? { name: vol, secret: { secretName: s["name"] as string, defaultMode: mode } }
          : { name: vol, secret: { secretName: s["name"] as string, defaultMode: mode, items: [{ key: s["key"] as string, path: fileName }] } };
      restart("Secret", s["name"]);
      break;
    case "certificate":
      volume = { name: vol, secret: { secretName: s["secretName"] as string, defaultMode: mode } };
      restart("Secret", s["secretName"]);
      break;
    case "image":
      volume = { name: vol, image: { reference: s["reference"] as string, ...(s["pullPolicy"] ? { pullPolicy: s["pullPolicy"] as string } : {}) } };
      break;
    default: {
      // csi
      const spc = s["secretProviderClass"] as string;
      volume = { name: vol, csi: { driver: (s["driver"] as string | undefined) ?? "secrets-store.csi.k8s.io", readOnly: true, volumeAttributes: { secretProviderClass: spc } } };
      restart("SecretProviderClass", spc);
    }
  }
  out.volumes.push(volume);
  out.volumeMounts.push({ name: vol, mountPath: mountDir(f), readOnly: true });
  return out;
}

// ---- Overlays (#RenderOverlay) ----

/** A value as an overlay writes it: native types, a duration in its encoding (#OverlayData). */
function overlayNative(v: ContractVar, x: unknown): unknown {
  if (v.type !== "duration" || typeof x !== "string") return x;
  if (v.encoding === "seconds") {
    const ms = durationParts(x)[0];
    return ms % 1000 === 0 ? ms / 1000 : ms / 1000;
  }
  return renderDuration(x, v.encoding);
}

function overlayData(c: Contract, o: ContractOverlay, values: Obj): Obj {
  const out: Obj = {};
  for (const n of Object.keys(values).sort()) {
    const v = c.vars[n]!;
    const parts = (v.configKey ?? n).split(o.keySeparator);
    let at = out;
    for (const p of parts.slice(0, -1)) at = (at[p] ??= {}) as Obj;
    at[parts[parts.length - 1]!] = overlayNative(v, values[n]);
  }
  return out;
}

function renderOverlay(c: Contract, name: string, o: ContractOverlay, values: Obj): { configMap: ConfigMapSpec; volume: Volume; volumeMount: VolumeMount } {
  const data = overlayData(c, o, values);
  const content = o.format === "json" ? JSON.stringify(data, null, 2) + "\n" : o.format === "yaml" ? yamlStringify(data) : tomlStringify(data);
  const fileName = posix.basename(o.path);
  const watch = o.reload === "watch";
  const cm = watch ? `${c.metadata.name}-overlay-${name}` : `${c.metadata.name}-overlay-${name}-${hash10(content)}`;
  return {
    configMap: { name: cm, data: { [fileName]: content }, ...(watch ? {} : { immutable: true }) },
    volume: { name: `dc-overlay-${name}`, configMap: { name: cm, defaultMode: 0o444, items: [{ key: fileName, path: fileName }] } },
    volumeMount: { name: `dc-overlay-${name}`, mountPath: posix.dirname(o.path), readOnly: true },
  };
}

// ---- Pod metadata (#PodMetadata) ----

const PLACEHOLDER = /\{(input|path|dir|file)\}/;
const QUALIFIED = /^([a-z0-9]([-a-z0-9]*[a-z0-9])?(\.[a-z0-9]([-a-z0-9]*[a-z0-9])?)*\/)?[A-Za-z0-9]([-A-Za-z0-9_.]{0,61}[A-Za-z0-9])?$/;
const QUALIFIED_LEN = /^([^/]{1,253}\/)?[^/]+$/;
const LABEL_VALUE = /^([A-Za-z0-9]([-A-Za-z0-9_.]{0,61}[A-Za-z0-9])?)?$/;
const QUALIFIED_RULE =
  'a Kubernetes qualified name: an optional DNS-subdomain prefix (at most 253 characters) and "/", then at most 63 letters, digits, "-", "_" and ".", starting and ending with a letter or digit';
const LABEL_RULE = 'at most 63 letters, digits, "-", "_" and ".", starting and ending with a letter or digit, or empty';
const PROVIDER = /^[a-z0-9]([-a-z0-9.]{0,61}[a-z0-9])?$/;
const FIELD_PATH = /^(metadata\.name|metadata\.namespace|metadata\.uid|spec\.nodeName|spec\.serviceAccountName|status\.hostIP|status\.podIP|metadata\.(labels|annotations)\['[^']+'\])$/;
const RESOURCES = ["limits.cpu", "limits.memory", "limits.ephemeral-storage", "requests.cpu", "requests.memory", "requests.ephemeral-storage"];

interface PodSource {
  /** The input's name, or undefined for the shared podMetadata. */
  input?: string;
  file?: ContractFile;
  annotations: Record<string, string>;
  labels: Record<string, string>;
}

function expand(s: string, input: string | undefined, f: ContractFile | undefined): string {
  if (input !== undefined) s = replaceAll(s, "{input}", input);
  if (f !== undefined) s = replaceAll(replaceAll(replaceAll(s, "{path}", f.path), "{dir}", mountDir(f)), "{file}", posix.basename(f.path));
  return s;
}

function podSource(input: string | undefined, f: ContractFile | undefined, from: { podAnnotations?: unknown; podLabels?: unknown }): PodSource {
  const ex = (m: unknown) => Object.fromEntries(Object.entries((m ?? {}) as Record<string, string>).map(([k, v]) => [expand(k, input, f), expand(String(v), input, f)]));
  return { input, file: f, annotations: ex(from.podAnnotations), labels: ex(from.podLabels) };
}

function podProblems(sources: PodSource[]): string[] {
  const out: string[] = [];
  for (const s of sources) {
    const who = s.input;
    for (const [field, m] of [["podAnnotations", s.annotations], ["podLabels", s.labels]] as const) {
      for (const [k, v] of Object.entries(m)) {
        if (PLACEHOLDER.test(k) || PLACEHOLDER.test(v)) {
          if (who === undefined) out.push(`${field} ${k}: uses a placeholder, which only an injected input's own podAnnotations and podLabels can`);
          else if (s.file) out.push(`${who}: ${field} ${k}: uses a placeholder this input does not define`);
          else out.push(`${who}: ${field} ${k}: uses {path}, {dir} or {file}, which only a file input defines; a variable has {input}`);
          continue;
        }
        const what = field === "podAnnotations" ? "annotation" : "label";
        if (!QUALIFIED.test(k) || !QUALIFIED_LEN.test(k)) {
          out.push(who === undefined ? `${field}: key ${JSON.stringify(k)} is not ${QUALIFIED_RULE}` : `${who}: pod ${what} key ${JSON.stringify(k)} is not ${QUALIFIED_RULE}`);
        } else if (field === "podLabels" && !LABEL_VALUE.test(v)) {
          out.push(who === undefined ? `podLabels ${k}: value ${JSON.stringify(v)} is not a label value: ${LABEL_RULE}` : `${who}: pod label ${k}: value ${JSON.stringify(v)} is not a label value: ${LABEL_RULE}`);
        }
      }
    }
  }
  // Two sources that set one key to different values (#PodMetadataConflicts).
  const label = (s: PodSource, field: string) => s.input ?? `the shared podMetadata.${field}`;
  for (const [field, get] of [["annotations", (s: PodSource) => s.annotations], ["labels", (s: PodSource) => s.labels]] as const) {
    const seen = new Map<string, PodSource>();
    for (const s of sources) {
      for (const [k, v] of Object.entries(get(s))) {
        const first = seen.get(k);
        if (first === undefined) seen.set(k, s);
        else if (get(first)[k] !== v) {
          const [a, b] = [label(first, field), label(s, field)].sort();
          out.push(`pod${field === "annotations" ? "Annotations" : "Labels"} ${k}: set to different values by ${a} and ${b}`);
        }
      }
    }
  }
  return out;
}

function podMerge(sources: PodSource[]): { annotations: Record<string, string>; labels: Record<string, string> } {
  const annotations: Record<string, string> = {};
  const labels: Record<string, string> = {};
  for (const s of sources) {
    Object.assign(annotations, s.annotations);
    Object.assign(labels, s.labels);
  }
  return { annotations, labels };
}

// ---- Rendering: arguments with every Input resolved ----

export interface Resolved {
  args: Args;
  overlayValues: Record<string, Obj>;
  podMetadata: PodMetadata;
}

/** The pod metadata sources, in #Render's order: shared, then variables, then file inputs. */
function podSources(c: Contract, r: Resolved): PodSource[] {
  const out = [podSource(undefined, undefined, { podAnnotations: r.podMetadata.annotations, podLabels: r.podMetadata.labels })];
  for (const n of Object.keys(c.vars)) {
    const a = r.args[n];
    if (isObj(a) && isObj(a["injected"])) out.push(podSource(n, undefined, a["injected"]));
  }
  for (const [n, f] of Object.entries(c.files ?? {})) {
    const a = r.args[n];
    if (isObj(a) && isObj(a["injected"])) out.push(podSource(n, f, a["injected"]));
  }
  return out;
}

/** #Render, for arguments that passed the checks. */
export function render(c: Contract, r: Resolved): Rendered {
  const env: EnvVar[] = [];
  for (const [n, v] of Object.entries(c.vars)) {
    const a = r.args[n];
    if (isObj(a)) env.push(...renderVar(n, v, a));
  }
  const files: FileParts[] = [];
  for (const [n, f] of Object.entries(c.files ?? {})) {
    const a = r.args[n];
    if (isObj(a)) files.push(renderFile(c.metadata.name, n, f, a));
  }
  const overlays = Object.entries(c.overlays ?? {})
    .filter(([n]) => r.overlayValues[n] !== undefined)
    .map(([n, o]) => renderOverlay(c, n, o, r.overlayValues[n]!));
  const pod = podMerge(podSources(c, r));
  return {
    env: [...env, ...files.flatMap((f) => f.env)],
    volumes: [...files.flatMap((f) => f.volumes), ...overlays.map((o) => o.volume)],
    volumeMounts: [...files.flatMap((f) => f.volumeMounts), ...overlays.map((o) => o.volumeMount)],
    configMaps: [...files.flatMap((f) => f.configMaps), ...overlays.map((o) => o.configMap)],
    restartTriggers: files.flatMap((f) => f.restartTriggers),
    podAnnotations: pod.annotations,
    podLabels: pod.labels,
  };
}

// ---- Checks ----

const declarations = new WeakMap<Contract, ContractDeclaration>();
function declaration(c: Contract): ContractDeclaration {
  let d = declarations.get(c);
  if (d === undefined) {
    // Overlays are left out: the checks take each overlay value directly,
    // and contract-first loading refuses overlays the app reloads.
    const { overlays: _overlays, ...rest } = c;
    d = parseContract(rest);
    declarations.set(c, d);
  }
  return d;
}

let emptyRoot: string | undefined;
/** A file root holding nothing, so value checks never read the deploying machine's files. */
function noFiles(): string {
  emptyRoot ??= mkdtempSync(join(tmpdir(), "docuconf-"));
  return emptyRoot;
}

/** A literal's problems, as the app would report them at boot. */
export function valueProblems(c: Contract, name: string, x: unknown, suffix = ""): { problems: string[]; warnings: string[] } {
  const v = c.vars[name]!;
  // What the SDK cannot see in the rendered text: precision a duration's
  // encoding drops, and an empty list, which renders as an unset variable.
  if (v.type === "duration" && typeof x === "string" && DURATION.test(x) && (v.encoding ?? "go") !== "go" && durationParts(x)[1] !== 0) {
    return { problems: [`${name}: ${x} is finer than a millisecond, which the ${v.encoding} encoding cannot carry (invalid_type)${suffix}`], warnings: [] };
  }
  const min = typeof v["minItems"] === "number" ? (v["minItems"] as number) : undefined;
  if (v.type === "list" && Array.isArray(x) && x.length === 0) {
    return { problems: min !== undefined && min > 0 ? [`${name}: must have at least ${min} items, has 0 (too_few_items)${suffix}`] : [], warnings: [] };
  }
  const env = Object.fromEntries(wireEntries(name, v, x).map((e) => [e.name, e.value]));
  const r = checkContract(declaration(c), env, { fileRoot: noFiles() });
  return {
    problems: r.violations.filter((p) => p.input === name && p.code !== "missing_required").map((p) => `${name}: ${p.message} (${p.code})${suffix}`),
    warnings: r.warnings.filter((w) => w.startsWith(name + " ") || w.startsWith(name + ":")),
  };
}

/** Inline file content's problems, as the app would report them at boot. */
export function inlineProblems(c: Contract, name: string, content: string): string[] {
  const f = c.files![name]!;
  const root = mkdtempSync(join(tmpdir(), "docuconf-"));
  try {
    const file = join(root, f.path);
    mkdirSync(posix.dirname(file), { recursive: true });
    writeFileSync(file, content);
    const r = checkContract(declaration(c), {}, { fileRoot: root });
    return r.violations.filter((p) => p.input === name).map((p) => `${name}: ${p.message} (${p.code})`);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
}

function hasOutput(x: unknown): boolean {
  if (pulumi.Output.isInstance(x) || x instanceof Promise) return true;
  if (Array.isArray(x)) return x.some(hasOutput);
  if (isObj(x)) return Object.values(x).some(hasOutput);
  return false;
}

/** The variables an overlay can carry, or why not (vet's reasons). */
function overlayReason(c: Contract, n: string, o: string): string | undefined {
  const v = c.vars[n];
  if (v === undefined) return `is not declared in the contract (check the spelling; in overlay ${o})`;
  if (isSecret(v)) return `is secret, so it cannot go in overlay ${o} (a ConfigMap); supply it in the environment as a secretKeyRef or injected`;
  if (!v.configKey) return `has no configKey in the contract, so overlay ${o} has nowhere to put it`;
  if (c.profiles?.selector === n) return `is the profile selector, which only the environment can set, not overlay ${o}`;
  if (v.configKey.split(c.overlays![o]!.keySeparator).length > 8) return `configKey ${v.configKey} is nested deeper than 8 levels`;
  return undefined;
}

function profileSupplies(c: Contract, n: string): boolean {
  return Object.values(c.profiles?.defaults ?? {}).some((m) => n in m);
}

/**
 * The checks that need no resolved Input: which arguments and sources are
 * set, inline content, overlays, and anything else the program writes as a
 * literal. Returns the problems and the deprecation warnings.
 */
export function structureProblems(
  c: Contract,
  args: Args,
  overlayValues: Record<string, unknown>,
  podMetadata?: unknown,
): { problems: string[]; warnings: string[] } {
  const problems: string[] = [];
  const warnings: string[] = [];
  const files = c.files ?? {};
  for (const k of Object.keys(args)) {
    if (args[k] !== undefined && !(k in c.vars) && !(k in files)) problems.push(`${k}: is not declared in the contract`);
  }
  const inOverlay = (n: string) => Object.keys(c.overlays ?? {}).filter((o) => isObj(overlayValues[o]) && (overlayValues[o] as Obj)[n] !== undefined);

  for (const [n, v] of Object.entries(c.vars)) {
    const a = args[n];
    const srcs = varSources(v);
    if (a === undefined || a === null) {
      if (v.required && inOverlay(n).length === 0 && !profileSupplies(c, n)) problems.push(`${n}: required, but not set (missing_required)`);
      continue;
    }
    if (pulumi.Output.isInstance(a)) {
      problems.push(`${n}: give the source as an object, such as { value: ... }, with any Output inside it`);
      continue;
    }
    const kind = sourceOf(a, VAR_SOURCES);
    if (kind === undefined || !srcs.includes(kind)) {
      if (isObj(a) && "value" in a && isSecret(v)) problems.push(`${n}: is secret, so it is never a value; set it with ${orList(srcs)}`);
      else problems.push(`${n}: set exactly one of ${orList(srcs)}`);
      continue;
    }
    const s = (a as Obj)[kind];
    if (kind === "injected" && isObj(s) && !hasOutput(s["provider"]) && !PROVIDER.test(String(s["provider"] ?? ""))) {
      problems.push(`${n}: injected.provider must name the injector as a lowercase label, such as bank-vaults`);
    }
    if (kind === "injected" && isObj(s) && s["ref"] !== undefined && (v.type === "keySet" || v.type === "list") && (v.encoding ?? "csv") === "indexed") {
      problems.push(`${n}: an indexed list is spread over NAME__0, NAME__1, …, so one injected reference cannot carry it; let the injector set the variables, without ref`);
    }
    if (kind === "fieldRef" && isObj(s) && !hasOutput(s["fieldPath"]) && !FIELD_PATH.test(String(s["fieldPath"]))) {
      problems.push(`${n}: fieldRef.fieldPath ${JSON.stringify(s["fieldPath"])} is not a Downward API field`);
    }
    if (kind === "resourceFieldRef" && isObj(s) && !hasOutput(s["resource"]) && !RESOURCES.includes(String(s["resource"]))) {
      problems.push(`${n}: resourceFieldRef.resource ${JSON.stringify(s["resource"])} is not a container resource`);
    }
    // The SDK warns about a deprecated value it checks; a reference it
    // never sees is warned about here.
    if (v.deprecated && kind !== "value") warnings.push(deprecatedWarning(n, v.deprecated));
    // A plain literal is checked now, with the others, so every problem
    // is reported at once; an Output is checked when it resolves.
    if (kind === "value" && !hasOutput(s)) {
      const r = valueProblems(c, n, s);
      problems.push(...r.problems);
      warnings.push(...r.warnings);
    }
    for (const o of inOverlay(n)) problems.push(`${n}: is set both in the environment and in overlay ${o}; set it in one place (the environment would win)`);
  }

  for (const [n, f] of Object.entries(files)) {
    const a = args[n];
    const srcs = fileSources(f);
    if (a === undefined || a === null) {
      if (f.required) problems.push(`${n}: is a required file input; set one of ${orList(srcs)}`);
      continue;
    }
    const kind = sourceOf(a, FILE_SOURCES);
    if (kind === undefined || !srcs.includes(kind)) {
      problems.push(`${n}: set exactly one of ${orList(srcs)}${f.secret ? " (a secret file comes from a secret store)" : ""}`);
      continue;
    }
    const s = (a as Obj)[kind];
    const fileName = posix.basename(f.path);
    if (f.deprecated) warnings.push(deprecatedWarning(n, f.deprecated));
    if (kind === "inline") {
      if (hasOutput(s)) {
        problems.push(`${n}: inline content is written into the platform's code; give it as a value, not an Output`);
        continue;
      }
      if (typeof s !== "string" && f.type !== "config") {
        problems.push(`${n}: inline content must be text for a ${f.type} file`);
        continue;
      }
      if (typeof s !== "string" && (typeof s !== "object" || s === null)) {
        problems.push(`${n}: inline content must be text, or an object or a list to write as ${f.format}`);
        continue;
      }
      problems.push(...inlineProblems(c, n, inlineContent(f, s)));
      continue;
    }
    if (!isObj(s)) {
      problems.push(`${n}: ${kind} must be an object`);
      continue;
    }
    if ((kind === "configMap" || kind === "secret") && f.type !== "tls" && (s["key"] === undefined || s["key"] === null)) {
      problems.push(`${n}: ${kind}.key is required: name the key that holds ${fileName}`);
    }
    if (kind === "secret" && f.type === "tls" && s["key"] !== undefined && s["key"] !== null) {
      problems.push(`${n}: a tls input mounts the whole Secret; remove secret.key`);
    }
    if (kind === "injected" && !hasOutput(s["provider"]) && !PROVIDER.test(String(s["provider"] ?? ""))) {
      problems.push(`${n}: injected.provider must name the injector as a lowercase label, such as bank-vaults`);
    }
    if (kind === "image" && s["pullPolicy"] !== undefined && !["Always", "IfNotPresent", "Never"].includes(s["pullPolicy"] as string)) {
      problems.push(`${n}: image.pullPolicy ${JSON.stringify(s["pullPolicy"])} is not one of Always, IfNotPresent, Never`);
    }
    if (kind === "certificate") problems.push(...certificateProblems(n, f, s));
  }

  for (const [o, values] of Object.entries(overlayValues)) {
    if (values === undefined) continue;
    if (!(o in (c.overlays ?? {}))) {
      problems.push(`overlayValues.${o}: is not an overlay in the contract`);
      continue;
    }
    if (!isObj(values) || hasOutput(values)) {
      problems.push(`overlayValues.${o}: must be an object of variable names and values, written into the platform's code (no Outputs)`);
      continue;
    }
    for (const [n, x] of Object.entries(values)) {
      if (x === undefined) continue;
      const why = overlayReason(c, n, o);
      if (why !== undefined) {
        problems.push(`${n}: ${why}`);
        continue;
      }
      if (isObj(x) && VAR_SOURCES.some((k) => k !== "value" && k in x)) {
        problems.push(`${n}: overlay ${o} holds values, not references; give a literal, or supply the reference in the environment`);
        continue;
      }
      const typeProblem = overlayTypeProblem(c.vars[n]!, x);
      if (typeProblem !== undefined) {
        problems.push(`${n}: ${typeProblem} (in overlay ${o})`);
        continue;
      }
      const r = valueProblems(c, n, x, ` (in overlay ${o})`);
      problems.push(...r.problems);
      warnings.push(...r.warnings);
    }
  }
  for (const n of Object.keys(c.vars)) {
    if (inOverlay(n).length > 1) problems.push(`${n}: is set in more than one overlay; set it in one place`);
  }
  // Pod metadata written as literals is checked now; with an Output in
  // it, when it resolves.
  if (!hasOutput(podMetadata) && problems.length === 0) {
    const sources = podSources(c, { args, overlayValues: {}, podMetadata: (podMetadata ?? {}) as PodMetadata });
    if (!sources.some((x) => hasOutput(x.annotations) || hasOutput(x.labels))) problems.push(...podProblems(sources));
  }
  return { problems, warnings };
}

/** An overlay value of the wrong native type, with vet's message; overlays keep types that env text loses. */
function overlayTypeProblem(v: ContractVar, x: unknown): string | undefined {
  const got = `got ${JSON.stringify(x)}`;
  switch (v.type) {
    case "int":
      return typeof x === "number" && Number.isInteger(x) ? undefined : `expected an integer, ${got}`;
    case "float":
      return typeof x === "number" ? undefined : `expected a number, ${got}`;
    case "bool":
      return typeof x === "boolean" ? undefined : `expected true or false, ${got}`;
    case "json":
      return undefined;
    case "list": {
      const ints = v.items === "int";
      const ok = Array.isArray(x) && x.every((i) => (ints ? typeof i === "number" && Number.isInteger(i) : typeof i === "string"));
      return ok ? undefined : `expected a list of ${v.items ?? "string"}s, ${got}`;
    }
    case "url":
      return typeof x === "string" ? undefined : `expected a URL string, ${got}`;
  }
  return typeof x === "string" ? undefined : `expected a string, ${got}`;
}

/** The SDK's deprecation warning. */
function deprecatedWarning(n: string, d: { message: string; replacedBy?: string }): string {
  const by = d.replacedBy !== undefined && !d.message.includes(d.replacedBy) ? ` (replaced by ${d.replacedBy})` : "";
  return `${n} is deprecated: ${d.message}${by}`;
}

function certificateProblems(n: string, f: ContractFile, s: Obj): string[] {
  const out: string[] = [];
  const names = s["dnsNames"];
  if (Array.isArray(names) && !hasOutput(names)) {
    for (const d of f.dnsNames ?? []) {
      const i = d.indexOf(".");
      const wildcard = i >= 0 ? "*" + d.slice(i) : "";
      if (!names.includes(d) && !names.includes(wildcard)) out.push(`${n}: certificate does not cover ${d}`);
    }
  }
  const alg = (s["privateKey"] as Obj | undefined)?.["algorithm"];
  if (f.keyAlgorithms && typeof alg === "string" && !f.keyAlgorithms.includes(alg)) {
    out.push(`${n}: certificate key algorithm ${alg} is not one of ${f.keyAlgorithms.join(", ")}`);
  }
  for (const field of ["duration", "renewBefore"]) {
    const x = s[field];
    if (typeof x === "string" && !DURATION.test(x)) out.push(`${n}: certificate.${field} ${JSON.stringify(x)} is not a duration such as 1m30s`);
  }
  const rb = s["renewBefore"];
  if (f.minRemaining && typeof rb === "string" && DURATION.test(rb) && durationLess(rb, f.minRemaining)) {
    out.push(`${n}: certificate renewBefore ${rb} is less than minRemaining ${f.minRemaining}, so the app could see a certificate with too little time left`);
  }
  return out;
}

// ---- The component's outputs ----

export interface KubernetesOutputs {
  kubernetesEnv: pulumi.Output<EnvVar[]>;
  kubernetesVolumes: pulumi.Output<Volume[]>;
  kubernetesVolumeMounts: pulumi.Output<VolumeMount[]>;
  /** Known when the component is constructed: inline content and overlays are literals. */
  kubernetesConfigMaps: ConfigMapSpec[];
  restartTriggers: pulumi.Output<RestartTrigger[]>;
  podAnnotations: pulumi.Output<Record<string, string>>;
  podLabels: pulumi.Output<Record<string, string>>;
  bindings: Bindings;
  /** Resolves when every value has passed its checks; fails with a ConfigViolation otherwise. */
  checked: pulumi.Output<boolean>;
}

/** Which source sets each input (the bindings output). */
export function bindings(c: Contract, args: Args, overlayValues: Record<string, unknown>): Bindings {
  const out: Bindings = {};
  for (const n of Object.keys(c.vars)) {
    const o = Object.keys(c.overlays ?? {}).find((o) => isObj(overlayValues[o]) && (overlayValues[o] as Obj)[n] !== undefined);
    const kind = sourceOf(args[n], VAR_SOURCES);
    out[n] = { set: kind !== undefined || o !== undefined, source: kind ?? (o !== undefined ? `overlay:${o}` : null) };
  }
  for (const n of Object.keys(c.files ?? {})) {
    const kind = sourceOf(args[n], FILE_SOURCES);
    out[n] = { set: kind !== undefined, source: kind ?? null };
  }
  return out;
}

/**
 * Checks and renders a component's arguments. Problems that need no
 * resolved Input throw a ConfigViolation at once; a value's problems throw
 * one when it resolves, which fails every output.
 */
export function kubernetes(
  self: pulumi.ComponentResource,
  c: Contract,
  args: Args,
  options: { overlayValues?: Record<string, unknown>; podMetadata?: pulumi.Input<PodMetadata> } = {},
): KubernetesOutputs {
  const component = `${c.metadata.name} config`;
  const overlayValues = options.overlayValues ?? {};
  const structure = structureProblems(c, args, overlayValues, options.podMetadata);
  if (structure.problems.length > 0) throw new ConfigViolation(component, structure.problems, self);
  for (const w of structure.warnings) pulumi.log.warn(w, self);

  // A value that is an Output is checked on its own, as soon as it
  // resolves, so a bad one that is known at preview fails the preview even
  // when another is not known yet.
  const checked: Record<string, pulumi.Output<unknown>> = {};
  for (const [n, v] of Object.entries(c.vars)) {
    const a = args[n];
    if (!isObj(a)) continue;
    const kind = sourceOf(a, VAR_SOURCES)!;
    const later = kind === "value" && hasOutput(a[kind]);
    checked[n] = (pulumi.output(a[kind] as pulumi.Input<unknown>) as pulumi.Output<unknown>).apply((x) => {
      if (later) {
        const r = valueProblems(c, n, x);
        if (r.problems.length > 0) throw new ConfigViolation(component, r.problems, self);
        for (const w of r.warnings) pulumi.log.warn(w, self);
      }
      return { [kind]: x };
    });
  }
  const fileArgs: Record<string, unknown> = {};
  for (const n of Object.keys(c.files ?? {})) if (args[n] !== undefined) fileArgs[n] = args[n];

  const rendered = pulumi
    .all([pulumi.all(checked), pulumi.output(fileArgs), pulumi.output(options.podMetadata ?? {})])
    .apply(([vars, files, podMetadata]) => {
      const r: Resolved = { args: { ...(vars as Args), ...(files as Args) }, overlayValues: overlayValues as Record<string, Obj>, podMetadata: podMetadata as PodMetadata };
      const problems = podProblems(podSources(c, r));
      if (problems.length > 0) throw new ConfigViolation(component, problems, self);
      return render(c, r);
    });

  // ConfigMaps hold only literals, so they are known now, and the program
  // can declare one resource for each.
  const literal: Resolved = { args: {}, overlayValues: overlayValues as Record<string, Obj>, podMetadata: {} };
  for (const [n, a] of Object.entries(fileArgs)) if (sourceOf(a, FILE_SOURCES) === "inline") literal.args[n] = a;
  const configMaps = render(c, literal).configMaps;

  return {
    kubernetesEnv: rendered.env,
    kubernetesVolumes: rendered.volumes,
    kubernetesVolumeMounts: rendered.volumeMounts,
    kubernetesConfigMaps: configMaps,
    restartTriggers: rendered.restartTriggers,
    podAnnotations: rendered.podAnnotations,
    podLabels: rendered.podLabels,
    bindings: bindings(c, args, overlayValues),
    checked: pulumi.all([...Object.values(checked), rendered]).apply(() => true),
  };
}

// ---- The ecs and cloudrun targets (spec/IAC.md 5.1, 5.2) ----
//
// A variable is a literal, a reference the platform resolves when the
// task or instance starts, or injected. ECS mounts no files; Cloud Run
// mounts a file input from a Secret Manager secret, one file per secret.
// Neither expands $(VAR), so values are not escaped.

export type Target = "ecs" | "cloudrun";

const SM_ARN = /^arn:aws(-cn|-us-gov|-iso|-iso-b)?:secretsmanager:[a-z0-9-]+:[0-9]{12}:secret:[A-Za-z0-9/_+=.@-]+$/;
const SSM_ARN = /^arn:aws(-cn|-us-gov|-iso|-iso-b)?:ssm:[a-z0-9-]+:[0-9]{12}:parameter\/[A-Za-z0-9/_.-]+$/;
const BARE_REF = /^[A-Za-z0-9/_+=.@-]+$/;
const GCP_SECRET = /^(projects\/[a-z][a-z0-9-]{4,28}[a-z0-9]\/secrets\/)?[A-Za-z0-9_-]{1,255}$/;
const GCP_VERSION = /^(latest|[1-9][0-9]*)$/;
const TARGET_SOURCES = ["value", "secret", "injected"] as const;

/** The sources a variable accepts on ecs and cloudrun. */
export function targetVarSources(v: ContractVar): string[] {
  // One variable per key: no single secret carries it, but an injector can set the variables.
  if (isSecret(v) && v.encoding === "indexed") return ["injected"];
  return isSecret(v) ? ["secret", "injected"] : ["value", "injected"];
}

/** The file inputs a target can deliver: none on ecs; on cloudrun, all but tls directories. */
export function targetFiles(c: Contract, target: Target): [string, ContractFile][] {
  if (target === "ecs") return [];
  return Object.entries(c.files ?? {}).filter(([, f]) => f.type !== "tls");
}

/** secrets[].valueFrom as ECS takes it: the ARN, then any selectors (arn:json-key:stage:id). */
function ecsValueFrom(s: Obj): string {
  const sel = [s["jsonKey"], s["versionStage"], s["versionId"]];
  if (sel.every((x) => x === undefined || x === null)) return s["valueFrom"] as string;
  return `${s["valueFrom"]}:${sel.map((x) => (x === undefined || x === null ? "" : x)).join(":")}`;
}

function secretHint(target: Target, v: ContractVar, srcs: string[]): string {
  const what = target === "ecs" ? "one ECS secret" : "one secret version";
  if (isSecret(v) && !srcs.includes("secret")) return ` (an indexed key set is one variable per key, which ${what} cannot carry)`;
  if (isSecret(v)) return " (a secret is never a literal value)";
  return target === "ecs" ? " (ECS has no ConfigMaps or Downward API)" : " (Cloud Run has no ConfigMaps or Downward API)";
}

function gcpSecretProblems(n: string, s: Obj): string[] {
  const out: string[] = [];
  const secret = s["secret"];
  if (!hasOutput(secret) && !GCP_SECRET.test(String(secret ?? ""))) {
    out.push(`${n}: secret.secret ${JSON.stringify(secret)} is not a Secret Manager secret ID or projects/PROJECT/secrets/SECRET`);
  }
  const version = s["version"] ?? "latest";
  if (!hasOutput(version) && !GCP_VERSION.test(String(version))) {
    out.push(`${n}: secret.version ${JSON.stringify(version)} is not latest or a version number`);
  }
  return out;
}

/** The checks on ecs and cloudrun that need no resolved Input. */
export function targetProblems(c: Contract, target: Target, args: Args): { problems: string[]; warnings: string[] } {
  const problems: string[] = [];
  const warnings: string[] = [];
  const files = new Map(targetFiles(c, target));
  for (const k of Object.keys(args)) {
    if (args[k] !== undefined && !(k in c.vars) && !files.has(k)) {
      problems.push(k in (c.files ?? {}) ? `${k}: the ${target} target cannot mount this file input` : `${k}: is not declared in the contract`);
    }
  }
  for (const [n, v] of Object.entries(c.vars)) {
    const a = args[n];
    const srcs = targetVarSources(v);
    if (a === undefined || a === null) {
      if (v.required && !profileSupplies(c, n)) problems.push(`${n}: required, but not set (missing_required)`);
      continue;
    }
    const kind = sourceOf(a, TARGET_SOURCES);
    if (kind === undefined || !srcs.includes(kind)) {
      problems.push(`${n}: set exactly one of ${orList(srcs)}${secretHint(target, v, srcs)}`);
      continue;
    }
    const s = (a as Obj)[kind];
    if (kind === "injected" && isObj(s)) {
      if (!hasOutput(s["provider"]) && !PROVIDER.test(String(s["provider"] ?? ""))) {
        problems.push(`${n}: injected.provider must name the injector as a lowercase label, such as bank-vaults`);
      }
      if (s["ref"] === "") problems.push(`${n}: injected.ref cannot be empty; leave it out when the injector sets the variable itself`);
      if (s["ref"] !== undefined && (v.type === "list" || v.type === "keySet") && v.encoding === "indexed") {
        problems.push(`${n}: an indexed list is spread over NAME__0, NAME__1, …, so one injected reference cannot carry it; let the injector set the variables, without ref`);
      }
    }
    if (kind === "secret" && isObj(s)) {
      if (target === "ecs") {
        const vf = s["valueFrom"];
        if (!hasOutput(vf)) {
          const from = String(vf ?? "");
          if (!SM_ARN.test(from) && !SSM_ARN.test(from) && !BARE_REF.test(from)) {
            problems.push(`${n}: secret.valueFrom ${JSON.stringify(vf)} is not a Secrets Manager ARN, a Parameter Store ARN, or the name of a secret or parameter`);
          } else if (["jsonKey", "versionStage", "versionId"].some((k) => s[k] !== undefined) && !SM_ARN.test(from)) {
            problems.push(`${n}: secret.jsonKey, versionStage and versionId select from a Secrets Manager secret, so secret.valueFrom must be its full ARN`);
          }
        }
        if (s["versionStage"] !== undefined && s["versionId"] !== undefined) problems.push(`${n}: set secret.versionStage or secret.versionId, not both`);
      } else {
        problems.push(...gcpSecretProblems(n, s));
      }
    }
    if (v.deprecated && kind !== "value") warnings.push(deprecatedWarning(n, v.deprecated));
    if (kind === "value" && !hasOutput(s)) {
      const r = valueProblems(c, n, s);
      problems.push(...r.problems);
      warnings.push(...r.warnings);
    }
  }
  for (const [n, f] of files) {
    const a = args[n];
    if (a === undefined || a === null) {
      if (f.required) problems.push(`${n}: is a required file input; set one of secret or injected`);
      continue;
    }
    const kind = sourceOf(a, ["secret", "injected"]);
    if (kind === undefined) {
      problems.push(`${n}: set exactly one of secret or injected (Cloud Run mounts files from Secret Manager)`);
      continue;
    }
    const s = (a as Obj)[kind];
    if (kind === "injected" && isObj(s) && !hasOutput(s["provider"]) && !PROVIDER.test(String(s["provider"] ?? ""))) {
      problems.push(`${n}: injected.provider must name the injector as a lowercase label, such as bank-vaults`);
    }
    if (kind === "secret" && isObj(s)) problems.push(...gcpSecretProblems(n, s));
    if (f.deprecated) warnings.push(deprecatedWarning(n, f.deprecated));
  }
  return { problems, warnings };
}

/** An ECS container definition's environment entry. */
export interface EcsEnvironmentEntry {
  name: string;
  value: string;
}
/** An ECS container definition's secrets entry. */
export interface EcsSecretEntry {
  name: string;
  valueFrom: string;
}
/** A Cloud Run (v2) container's env entry. */
export interface CloudRunEnv {
  name: string;
  value?: string;
  valueSource?: { secretKeyRef: { secret: string; version: string } };
}
/** A Cloud Run (v2) secret volume holding one file. */
export interface CloudRunVolume {
  name: string;
  secret: { secret: string; defaultMode: number; items: { version: string; path: string }[] };
}
export interface CloudRunVolumeMount {
  name: string;
  mountPath: string;
}

export interface TargetRendered {
  ecsEnvironment: EcsEnvironmentEntry[];
  ecsSecrets: EcsSecretEntry[];
  cloudrunEnv: CloudRunEnv[];
  cloudrunVolumes: CloudRunVolume[];
  cloudrunVolumeMounts: CloudRunVolumeMount[];
}

/** The ecs and cloudrun outputs, for arguments that passed the checks. */
export function renderTarget(c: Contract, target: Target, args: Args): TargetRendered {
  const out: TargetRendered = { ecsEnvironment: [], ecsSecrets: [], cloudrunEnv: [], cloudrunVolumes: [], cloudrunVolumeMounts: [] };
  for (const [n, v] of Object.entries(c.vars)) {
    const a = args[n];
    if (!isObj(a)) continue;
    const kind = sourceOf(a, TARGET_SOURCES)!;
    const s = a[kind];
    if (kind === "injected") {
      const ref = (s as Obj)["ref"];
      if (typeof ref === "string" && ref !== "") {
        out.ecsEnvironment.push({ name: n, value: ref });
        out.cloudrunEnv.push({ name: n, value: ref });
      }
    } else if (kind === "secret") {
      const m = s as Obj;
      out.ecsSecrets.push({ name: n, valueFrom: target === "ecs" ? ecsValueFrom(m) : "" });
      out.cloudrunEnv.push({ name: n, valueSource: { secretKeyRef: { secret: m["secret"] as string, version: (m["version"] as string | undefined) ?? "latest" } } });
    } else {
      for (const e of wireEntries(n, v, s)) {
        out.ecsEnvironment.push(e);
        out.cloudrunEnv.push(e);
      }
    }
  }
  for (const [n, f] of targetFiles(c, target)) {
    const a = args[n];
    if (!isObj(a)) continue;
    if (f.pathEnv) out.cloudrunEnv.push({ name: f.pathEnv, value: f.path });
    const s = a["secret"];
    if (!isObj(s)) continue;
    out.cloudrunVolumes.push({
      name: `dc-${n}`,
      secret: { secret: s["secret"] as string, defaultMode: f.secret ? 0o400 : 0o444, items: [{ version: (s["version"] as string | undefined) ?? "latest", path: posix.basename(f.path) }] },
    });
    out.cloudrunVolumeMounts.push({ name: `dc-${n}`, mountPath: mountDir(f) });
  }
  return out;
}

export interface TargetOutputs {
  rendered: pulumi.Output<TargetRendered>;
  bindings: Bindings;
  checked: pulumi.Output<boolean>;
}

/** Checks and renders a component's arguments on ecs or cloudrun, as kubernetes does for its target. */
export function forTarget(self: pulumi.ComponentResource, c: Contract, target: Target, args: Args): TargetOutputs {
  const component = `${c.metadata.name} config`;
  const structure = targetProblems(c, target, args);
  if (structure.problems.length > 0) throw new ConfigViolation(component, structure.problems, self);
  for (const w of structure.warnings) pulumi.log.warn(w, self);
  const checked: Record<string, pulumi.Output<unknown>> = {};
  const names = [...Object.keys(c.vars), ...targetFiles(c, target).map(([n]) => n)];
  for (const n of names) {
    const a = args[n];
    if (!isObj(a)) continue;
    const kind = sourceOf(a, TARGET_SOURCES)!;
    const later = kind === "value" && hasOutput(a[kind]);
    checked[n] = (pulumi.output(a[kind] as pulumi.Input<unknown>) as pulumi.Output<unknown>).apply((x) => {
      if (later) {
        const r = valueProblems(c, n, x);
        if (r.problems.length > 0) throw new ConfigViolation(component, r.problems, self);
        for (const w of r.warnings) pulumi.log.warn(w, self);
      }
      return { [kind]: x };
    });
  }
  const rendered = pulumi.all(checked).apply((resolved) => renderTarget(c, target, resolved as Args));
  const b: Bindings = {};
  for (const n of names) {
    const kind = sourceOf(args[n], TARGET_SOURCES);
    b[n] = { set: kind !== undefined, source: kind ?? null };
  }
  return { rendered, bindings: b, checked: rendered.apply(() => true) };
}
